}

export const calendarDropdownRecipe = defineRecipe<CalendarDropdownParams>({
  id: 'calendar-dropdown',
  kind: 'field',
  layers: ['rest', 'hover', 'focus', 'disabled', 'invalid'],
  lazy: ['focus', 'hover'],
  pad: 12,
